pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes calldata fuzzData) public {
        Spy spy = new Spy();
        try c.forward(address(spy), fuzzData) {
            bool calleeReceivedCall = spy.wasCalled();
            assertTrue(calleeReceivedCall);
        } catch {
        }
    }
}

contract Spy {
    bool public wasCalled;
    fallback(bytes calldata) external payable returns (bytes memory) {
        wasCalled = true;
        return "";
    }
}
